solucao.estilo.css:
/* 1. Tema: variáveis no :root */
:root {
  --cor-fundo: #0d1b2a;
  --cor-texto: #f0f4f8;
  --cor-destaque: #ffd23f;
  --cor-cartao: #1b2d45;
}

/* 2. Base: body, links e botões */
body {
  margin: 0;
  font-family: Verdana, sans-serif;
  line-height: 1.5;
  background-color: var(--cor-fundo);
  color: var(--cor-texto);
}

a {
  color: var(--cor-destaque);
}

.botao {
  display: inline-block;
  padding: 12px 24px;
  border-radius: 999px;
  background-color: var(--cor-destaque);
  color: var(--cor-fundo);
  font-weight: bold;
  text-decoration: none;
  transition: transform 0.2s ease-out;
}

.botao:hover {
  transform: scale(1.1);
}

/* 3. Cabeçalho grudado no topo */
.topo {
  position: sticky;
  top: 0;
  z-index: 10;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 24px;
  background-color: var(--cor-fundo);
  border-bottom: 1px solid var(--cor-cartao);
}

.logo {
  margin: 0;
  font-weight: bold;
  color: var(--cor-destaque);
}

.topo nav {
  display: flex;
  gap: 16px;
}

/* 4. Herói com o mascote animado */
.heroi {
  padding: 48px 24px;
  text-align: center;
}

.heroi h1 {
  margin: 16px 0 8px;
  font-size: clamp(32px, 8vw, 56px);
}

.mascote {
  animation: flutuar 3s ease-in-out infinite alternate;
}

@keyframes flutuar {
  from {
    transform: translateY(0);
  }
  to {
    transform: translateY(-20px);
  }
}

/* 5. Cartões em grade, com o selo no canto */
.recursos,
.baixar {
  max-width: 960px;
  margin: 0 auto;
  padding: 24px;
}

.baixar {
  text-align: center;
}

.grade {
  display: grid;
  gap: 16px;
}

.cartao {
  position: relative;
  padding: 24px 16px 16px;
  border-radius: 12px;
  background-color: var(--cor-cartao);
}

.selo {
  position: absolute;
  top: 12px;
  right: 12px;
  padding: 2px 8px;
  border-radius: 4px;
  background-color: var(--cor-destaque);
  color: var(--cor-fundo);
  font-size: 14px;
  font-weight: bold;
}

footer {
  padding: 24px;
  text-align: center;
}

/* 6. Celular primeiro: 3 colunas a partir de 700px */
@media (min-width: 700px) {
  .grade {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* 7. Movimento com cuidado (sempre por último) */
@media (prefers-reduced-motion: reduce) {
  .mascote {
    animation: none;
  }
}
